SELECT ?z ?l ?p ?s WHERE {
  ?z rdfs:label ?l .
  FILTER(?l IN ("Perimeter_top_ZN_1","Perimeter_top_ZN_4"))
  OPTIONAL { ?z ?rel ?p . ?p ref:hasTimeseriesId ?s . }
}

SELECT ?p ?pc ?s ?rel ?prel WHERE {
  ?z rdfs:label ?l .
  FILTER(?l IN ("Perimeter_top_ZN_1","Perimeter_top_ZN_4"))
  ?z ?rel ?p .
  OPTIONAL { ?p a ?pc }
  OPTIONAL { ?p ?prel ?s . }
}

SELECT ?zone ?point ?tsref WHERE {
  ?zone rdfs:label ?l .
  FILTER(?l IN ("Perimeter_top_ZN_1","Perimeter_top_ZN_4"))
  ?zone brick:hasPoint ?point .
  ?point brick:ref:hasExternalReference ?tsref .
}

SELECT ?zoneLabel ?point ?tsref ?pointclass WHERE {
  ?zone rdfs:label ?zoneLabel .
  FILTER(?zoneLabel IN ("Perimeter_top_ZN_1","Perimeter_top_ZN_4"))
  ?zone <https://brickschema.org/schema/Brick#hasPoint> ?point .
  OPTIONAL { ?point a ?pointclass . }
  OPTIONAL { ?point <https://brickschema.org/schema/Brick/ref#hasExternalReference> ?tsref . }
}

